CREATE TABLE orders (
  order_id   NUMBER PRIMARY KEY,
  order_doc  CLOB CONSTRAINT orders_doc_is_json CHECK (order_doc IS JSON)
);

INSERT INTO orders VALUES (1,
  '{"customer":{"name":"Asha Rao","city":"Pune"},
    "status":"SHIPPED",
    "items":[{"sku":"KB-101","qty":2,"price":1500},
             {"sku":"MS-220","qty":1,"price":650}]}');

