INSERT INTO orders VALUES (4,
  '{"customer":{"name":"Rahul Verma","city":"Delhi"},
    "status":"PENDING",
    "items":[{"sku":"KB-101","qty":"two","price":1500}]}');
COMMIT;

SELECT o.order_id, jt.qty
  FROM orders o,
       JSON_TABLE(o.order_doc, '$'
         COLUMNS (
           NESTED PATH '$.items[*]'
             COLUMNS (
               qty NUMBER PATH '$.qty' ERROR ON ERROR
             )
         )) jt;

DECLARE
  l_doc CLOB := '{"items":[{"sku":"KB-101","qty":2},
                           {"sku":"MS-220","qty":1}]}';
BEGIN
  FOR r IN (SELECT jt.sku, jt.qty
              FROM JSON_TABLE(l_doc, '$.items[*]'
                     COLUMNS (sku VARCHAR2(20) PATH '$.sku',
                              qty NUMBER       PATH '$.qty')) jt)
  LOOP
    DBMS_OUTPUT.PUT_LINE(r.sku || ' x ' || r.qty);
  END LOOP;
END;
